examples.template:
HStack(spacing: 12) {
    MonarchButton({{add}}, variant: .secondary) {
        count += 1
        AccessibilityNotification.Announcement(count == 1 ? "1 item in the list." : "\(count) items in the list.").post()
    }
    // The same message, shown, for people who do not use VoiceOver.
    Text(count == 0 ? {{empty}} : (count == 1 ? "1 item in the list." : "\(count) items in the list."))
        .monarchTextStyle(.body)
        .foregroundStyle(theme.colors.textMuted)
}

examples.code:
HStack(spacing: 12) {
    MonarchButton("Add item", variant: .secondary) {
        count += 1
        AccessibilityNotification.Announcement(count == 1 ? "1 item in the list." : "\(count) items in the list.").post()
    }
    // The same message, shown, for people who do not use VoiceOver.
    Text(count == 0 ? "No items yet." : (count == 1 ? "1 item in the list." : "\(count) items in the list."))
        .monarchTextStyle(.body)
        .foregroundStyle(theme.colors.textMuted)
}

MonarchButton("Upload") {
    var message = AttributedString("Upload failed. Check the connection.")
    message.accessibilitySpeechAnnouncementPriority = .high
    AccessibilityNotification.Announcement(message).post()
}
